// Review-only current Search: add a promo tag to the last restaurant result.
(()=>{const mount=()=>{const results=document.querySelector('[aria-label="Search results"]')||document;const cards=[...results.querySelectorAll('[role="button"]')].filter(card=>card.querySelector('[aria-label="Item photo gallery"]'));const last=cards.at(-1);if(!last||last.querySelector('[data-current-mealbox-badge]'))return;const text=[...last.querySelectorAll('div')].find(x=>x.textContent.trim()==='$0 delivery fee'&&x.children.length===0);if(!text)return;const badge=document.createElement('span');badge.dataset.currentMealboxBadge='';badge.textContent='$12 Meal Box';badge.style.cssText='display:inline-flex;align-items:center;align-self:flex-start;margin-top:4px;padding:2px 8px;border-radius:999px;background:#fff0ed;color:#d91400;font-family:"DD Norms",sans-serif;font-size:12px;font-weight:700;line-height:18px';text.parentElement.parentElement.parentElement.append(badge)};new MutationObserver(mount).observe(document.documentElement,{subtree:true,childList:true});mount()})();
